  fs.writeSync(handle, line+'\n');
};
    // ...
var writeJoint = function(erp, filename) {
  var handle = openFile(filename);
  var supp = erp.support();
   _.isObject(supp[0]) ?
   writeLine([_.keys(supp[0]),"prob"].join(','),
 handle) :
   null

   supp.forEach(function(s) {
     writeLine([
       _.values(s),
       Math.exp(erp.score(s))
     ].join(','), handle
     );
   })
   closeFile(handle);
};

